-- Illustrative synthetic data, not customer facts. Cutoff 2026-10-31. AUD repair spend, not revenue.
SELECT COUNT(*) JOBS,SUM(REPAIR_SPEND_CENTS)/100.0 REPAIR_SPEND_AUD,SUM(MISSING_INVOICE) COMPLETED_WITHOUT_INVOICE FROM DEMO_DATABASE.DEMO_SCHEMA.PROPERTYME_DEMO_MART_JOBS;
SELECT AGENCY_ID,STATUS,COUNT(*) JOBS,AVG(APPROVAL_HOURS) APPROVAL_HOURS,AVG(CASE WHEN STATUS!='completed' THEN AGE_AT_CUTOFF_HOURS END) OPEN_AGE_HOURS,AVG(COMPLETED_CYCLE_HOURS) COMPLETED_CYCLE_HOURS FROM DEMO_DATABASE.DEMO_SCHEMA.PROPERTYME_DEMO_MART_JOBS GROUP BY 1,2 ORDER BY 1,2;
SELECT JOB_ID,AGENCY_ID,STATUS,QUOTE_COUNT,REPAIR_SPEND_CENTS,MISSING_INVOICE FROM DEMO_DATABASE.DEMO_SCHEMA.PROPERTYME_DEMO_MART_JOBS WHERE MISSING_INVOICE=1 ORDER BY JOB_ID LIMIT 10;
SELECT J.AGENCY_ID,J.JOB_ID,J.REPAIR_SPEND_CENTS,Q.ACCEPTED_QUOTE_CENTS FROM DEMO_DATABASE.DEMO_SCHEMA.PROPERTYME_DEMO_MART_JOBS J LEFT JOIN (SELECT AGENCY_ID,JOB_ID,SUM(CASE WHEN ACCEPTED THEN QUOTE_CENTS ELSE 0 END) ACCEPTED_QUOTE_CENTS FROM DEMO_DATABASE.DEMO_SCHEMA.PROPERTYME_DEMO_QUOTES GROUP BY 1,2) Q ON J.AGENCY_ID=Q.AGENCY_ID AND J.JOB_ID=Q.JOB_ID ORDER BY J.JOB_ID LIMIT 10;
SELECT AGENCY_ID,PROPERTY_ID,CATEGORY,COUNT(*) REPAIR_JOBS FROM DEMO_DATABASE.DEMO_SCHEMA.PROPERTYME_DEMO_MART_JOBS GROUP BY 1,2,3 HAVING COUNT(*)>1 ORDER BY REPAIR_JOBS DESC,AGENCY_ID,PROPERTY_ID LIMIT 10;
SELECT P.AGENCY_ID,P.MANAGER_ID,P.PROPERTIES_MANAGED,COALESCE(J.JOBS,0) JOBS,COALESCE(J.JOBS,0)*100.0/P.PROPERTIES_MANAGED JOBS_PER_100_PROPERTIES FROM (SELECT AGENCY_ID,MANAGER_ID,COUNT(*) PROPERTIES_MANAGED FROM DEMO_DATABASE.DEMO_SCHEMA.PROPERTYME_DEMO_PROPERTIES GROUP BY 1,2) P LEFT JOIN (SELECT AGENCY_ID,MANAGER_ID,COUNT(*) JOBS FROM DEMO_DATABASE.DEMO_SCHEMA.PROPERTYME_DEMO_MART_JOBS GROUP BY 1,2) J ON P.AGENCY_ID=J.AGENCY_ID AND P.MANAGER_ID=J.MANAGER_ID ORDER BY 1,2;
